            [42, 'tunik-bordir-floral-sage', 'Tunik Bordir Floral Sage', 'Tunik modern dengan aksen bordir floral timbul di bagian dada dan pergelangan tangan. Memiliki siluet longgar yang santun dan anggun, dibuat dari katun rayon premium yang halus, adem seharian, serta tidak menerawang. Sangat pas untuk acara silaturahmi maupun outfit harian.', 215000, 285000, 25, 'blouse', 'Laras Atelier', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=900&q=85', 4.9, 310, 890, ['Bahan' => 'Katun Rayon Twill', 'Ukuran' => 'M, L, XL, XXL', 'Panjang Baju' => '105 cm', 'Fitur' => 'Resleting depan ramah busui'], ['ready to ship', 'best seller'], 'Jl. Margonda Raya No. 102, Depok'],
            [43, 'kemeja-formal-slim-fit-white', 'Kemeja Formal Premium Slim Fit Putih', 'Kemeja kerja pria berbahan fine cotton combed 100% yang breathable, tidak mudah kusut, dan memiliki potongan slim fit presisi. Dilengkapi kerah kaku berduri yang kokoh serta kancing mutiara eksklusif untuk penampilan profesional di kantor.', 189000, 259000, 27, 'kemeja', 'Daily Form', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=900&q=85', 4.8, 420, 1420, ['Bahan' => '100% Fine Combed Cotton', 'Ukuran' => 'S, M, L, XL, XXL', 'Kerah' => 'Spread Collar', 'Tipe Potongan' => 'Modern Slim Fit'], ['ready to ship'], 'Jl. Sudirman No. 45, Jakarta Selatan'],
            [44, 'hoodie-heavyweight-charcoal', 'Hoodie Oversized Heavyweight Charcoal', 'Hoodie berbahan fleece katun gramasi 330 gsm yang tebal, lembut di kulit, dan memberi kehangatan maksimal. Menggunakan double-layered hood dan rib spandex elastis di pinggang dan lengan yang tahan lama meski sering dicuci.', 279000, 369000, 24, 'outer', 'Northline', 'https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=900&q=85', 4.9, 524, 1680, ['Bahan' => 'Cotton Fleece 330 GSM', 'Ukuran' => 'M, L, XL, XXL', 'Warna' => 'Charcoal Heather', 'Fitur' => 'Saku kangguru besar & tali serut katun'], ['ready to ship', 'best seller'], 'Jl. Cihampelas No. 120, Bandung'],
            [45, 'celana-chino-stretch-navy', 'Celana Chino Slim Straight Navy', 'Celana chino kasual pria dengan material katun stretch berkualitas tinggi yang fleksibel mengikuti setiap pergerakan. Cocok dipadukan dengan kemeja kantor maupun t-shirt kasual untuk hangout di akhir pekan.', 239000, 319000, 25, 'celana', 'Forma Wear', 'https://images.unsplash.com/photo-1473966968600-fa801b869a1a?auto=format&fit=crop&w=900&q=85', 4.8, 380, 1150, ['Bahan' => 'Cotton Twill Stretch 3% Spandex', 'Ukuran' => '28 - 38', 'Warna' => 'Deep Navy', 'Ritsleting' => 'YKK Metal Zipper'], ['ready to ship'], 'Jl. Malioboro No. 88, Yogyakarta'],
            [46, 'gamis-abaya-linen-noir', 'Abaya Gamis Linen Modern Noir', 'Abaya dengan potongan A-line lebar yang jatuh anggun saat dipakai. Terbuat dari linen premium berserat rapat yang dingin dan menyerap keringat. Dilengkapi saku fungsional di kedua sisi serta detail kancing manset wudhu-friendly.', 345000, 450000, 23, 'dress', 'Maison Rona', 'https://images.unsplash.com/photo-1566174053879-31528523f8ae?auto=format&fit=crop&w=900&q=85', 4.9, 198, 540, ['Bahan' => 'Linen Pure Look Premium', 'Ukuran' => 'All Size fit to XL', 'Panjang' => '140 cm', 'Lingkar Dada' => '110 cm'], ['ready to ship', 'new'], 'Jl. Slamet Riyadi No. 45, Surakarta'],
            [47, 'jaket-parka-canvas-olive', 'Jaket Parka Canvas Hooded Olive', 'Jaket parka serbaguna berbahan canvas baby tebal dengan furing dormeuil england yang lembut. Dirancang dengan hoodie lepas-pasang, tali serut pinggang bagian dalam, serta 4 saku berkancing untuk keamanan barang bawaan.', 339000, 459000, 26, 'outer', 'Northline', 'https://images.unsplash.com/photo-1544441893-675973e31985?auto=format&fit=crop&w=900&q=85', 4.8, 175, 490, ['Bahan' => 'Baby Canvas & Furing Dormeuil', 'Ukuran' => 'M, L, XL', 'Warna' => 'Army Olive', 'Ketahanan' => 'Windproof ringan'], ['ready to ship'], 'Jl. Pandanaran No. 76, Semarang'],
            [48, 'sepatu-loafers-leather-mocca', 'Sepatu Loafers Casual Leather Mocca', 'Loafers klasik pria/wanita dengan upper kulit sintetis premium bertekstur matte yang tahan gores. Dilengkapi memory foam insole anti-pegal dan outsole TPR lentur anti-licin yang nyaman untuk dipakai seharian.', 289000, 399000, 28, 'alas kaki', 'Karsa Footwear', 'https://images.unsplash.com/photo-1533867617858-e7b97e060509?auto=format&fit=crop&w=900&q=85', 4.8, 290, 780, ['Bahan' => 'Microfiber Leather & TPR Outsole', 'Ukuran' => '39 - 44', 'Insole' => 'Ortholite Cushion 5mm', 'Warna' => 'Mocca Brown'], ['ready to ship', 'best seller'], 'Jl. Basuki Rahmat No. 62, Surabaya'],
            [49, 'rok-span-knit-rib-black', 'Rok Span Midi Knit Ribbed Hitam', 'Rok span rajut bergaris dengan tingkat elastisitas tinggi yang menyesuaikan bentuk tubuh tanpa rasa sesak. Material rajut premium tidak tembus pandang dan terdapat belahan belakang minimalis untuk kemudahan melangkah.', 149000, 199000, 25, 'rok', 'Atelier Senja', 'https://images.unsplash.com/photo-1509551388413-e18d0ac5d495?auto=format&fit=crop&w=900&q=85', 4.7, 430, 1310, ['Bahan' => 'Soft Knit Rib Premium', 'Ukuran' => 'All Size elastis (LP 64-96 cm)', 'Panjang' => '85 cm', 'Belahan' => 'Back Slit 18 cm'], ['ready to ship'], 'Jl. Sukajadi No. 90, Bandung'],
            [50, 'tas-ransel-laptop-waterproof', 'Backpack Laptop Minimalist Waterproof', 'Tas ransel urban berkapasitas 22 liter dengan kompartemen laptop khusus hingga ukuran 15.6 inci yang dilengkapi busa peredam benturan. Menggunakan bahan cordura bultproof tahan air dan ritsleting kedap air.', 265000, 350000, 24, 'tas', 'Kanvas Kita', 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=900&q=85', 4.9, 610, 1950, ['Bahan' => 'Water-repellent Cordura Nylon', 'Dimensi' => '44 x 30 x 14 cm', 'Kompartemen Laptop' => 'Busa tebal 15.6 inch', 'Fitur' => 'Luggage strap & USB port'], ['ready to ship', 'best seller'], 'Jl. Tebet Barat Dalam No. 34, Jakarta Selatan'],
            [51, 'blazer-formal-crop-beige', 'Blazer Crop Semi-Formal Beige', 'Blazer model crop modern dengan kerah lapel tajam dan kancing tunggal aksen tortoise. Potongan pundak dilengkapi shoulder pad proporsional yang membuat postur terlihat lebih tegap dan stylish untuk gaya smart-casual.', 295000, 399000, 26, 'outer', 'Maison Rona', 'https://images.unsplash.com/photo-1591369822096-ffd140ec948f?auto=format&fit=crop&w=900&q=85', 4.8, 160, 420, ['Bahan' => 'Semi Wool Poliester Premium', 'Ukuran' => 'S, M, L', 'Warna' => 'Warm Beige', 'Furing' => 'Full Furing Satin'], ['ready to ship', 'new'], 'Jl. Kaliurang Km 5.5 No. 12, Yogyakarta'],
            [52, 'pashmina-ceruty-babydoll-taupe', 'Pashmina Ceruty Babydoll Taupe', 'Pashmina bertekstur pasir lembut yang flowy, mudah diatur, dan tidak gerah saat dipakai. Dijahit dengan tepi kelim rapi kualitas butik dengan ukuran ekstra panjang untuk berbagai kreasi hijab modern.', 59000, 85000, 31, 'hijab', 'Ruang Syal', 'https://images.unsplash.com/photo-1584184924103-e310d9dc82fc?auto=format&fit=crop&w=900&q=85', 4.9, 870, 3200, ['Bahan' => 'Original Ceruty Babydoll Armani', 'Ukuran' => '180 x 75 cm', 'Jahitan' => 'Kelim Butik Presisi', 'Karakter' => 'Flowy & Mudah Dibentuk'], ['ready to ship', 'best seller'], 'Jl. Ijen Boulevard No. 40, Malang'],
            [53, 'kaos-polo-classic-pique-forest', 'Kaos Polo Shirt Classic Pique Forest Green', 'Kaos polo berkerah dengan rajutan kain katun pique 24s yang berpori teratur, menyerap keringat dengan sangat baik dan tetap sejuk di bawah terik matahari. Kerah rajut tidak mudah melipat setelah dicuci berulang kali.', 139000, 189000, 26, 'kaos', 'Daily Form', 'https://images.unsplash.com/photo-1581655353564-df123a1eb820?auto=format&fit=crop&w=900&q=85', 4.8, 340, 1080, ['Bahan' => 'Cotton Pique Diamond 24s', 'Ukuran' => 'S, M, L, XL, XXL', 'Warna' => 'Forest Green', 'Kancing' => '3 Butir Engraved'], ['ready to ship'], 'Jl. Gajah Mada No. 112, Semarang'],
            [54, 'vest-rajut-korea-ivory', 'Knit Vest Outerwear Korean Style Ivory', 'Rompi rajut model v-neck bergaya Korea dengan motif kabel timbul yang manis. Sangat ideal dijadikan outer di atas kemeja berkerah atau kaos oversized untuk menciptakan tampilan preppy look kontemporer.', 135000, 180000, 25, 'outer', 'Nusa Knit', 'https://images.unsplash.com/photo-1620799140408-edc6dcb6d633?auto=format&fit=crop&w=900&q=85', 4.7, 215, 670, ['Bahan' => 'Premium Acrylic Wool Knit 7 Gauge', 'Ukuran' => 'All Size Fit to L (LD 102 cm)', 'Model' => 'V-Neck Cable Knit', 'Warna' => 'Ivory Cream'], ['ready to ship', 'new'], 'Jl. Riau No. 42, Bandung'],
            [55, 'sepatu-chelsea-boots-black', 'Chelsea Boots Synthetic Leather Hitam', 'Sepatu boots model chelsea dengan panel karet elastis di sisi samping dan tab penarik belakang agar praktis dipakai tanpa tali. Sol bergerigi dari karet padat memberikan daya cengkeram kuat dan tampilan berkarakter.', 369000, 489000, 25, 'alas kaki', 'Karsa Footwear', 'https://images.unsplash.com/photo-1608256246200-53e635b5b65f?auto=format&fit=crop&w=900&q=85', 4.8, 195, 510, ['Bahan' => 'Synthetic Leather Matte & Heavy Duty Rubber', 'Ukuran' => '39 - 44', 'Tinggi Heels' => '3.5 cm', 'Desain' => 'Elastic Side Gusset'], ['ready to ship'], 'Jl. Pemuda No. 77, Surabaya'],
            [56, 'dompet-panjang-organizer-cognac', 'Dompet Panjang Leather Organizer Cognac', 'Dompet panjang pria/wanita dengan 12 slot kartu, kompartemen resleting untuk koin, dan dua kantong utama yang cukup untuk menyimpan smartphone tipis. Jahitan tangan di sekeliling dompet menjamin daya tahan penggunaan bertahun-tahun.', 189000, 269000, 30, 'aksesoris', 'Kanvas Kita', 'https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&w=900&q=85', 4.9, 275, 830, ['Bahan' => 'Crazy Horse Synthetic Microfiber', 'Dimensi' => '19.5 x 9.5 x 2 cm', 'Slot' => '12 Kartu, 1 Zipper Koin, 3 Sekat Uang', 'Warna' => 'Vintage Cognac'], ['ready to ship'], 'Jl. Kemang Raya No. 33, Jakarta Selatan'],
        ];

        $locationCoordinates = [
            'Jakarta' => [-6.2088, 106.8456],
            'Bandung' => [-6.9175, 107.6191],
            'Yogyakarta' => [-7.7956, 110.3695],
            'Surakarta' => [-7.5755, 110.8243],
            'Semarang' => [-6.9667, 110.4167],
            'Surabaya' => [-7.2575, 112.7521],
            'Malang' => [-7.9666, 112.6326],
            'Depok' => [-6.4025, 106.7942],
        ];

        return array_map(static function (array $item) use ($locationCoordinates): array {
            [$id, $slug, $name, $description, $price, $originalPrice, $discount, $category, $brand, $image, $rating, $reviews, $sold, $specifications, $tags, $address] = $item;
            $mapUrl = 'https://www.google.com/maps/search/?api=1&query='.urlencode($address);
            $coordinates = collect($locationCoordinates)->first(
                static fn (array $coordinate, string $city): bool => str_contains($address, $city),
                [-6.2088, 106.8456]
            );

            return [
                'id' => $id, 'slug' => $slug, 'name' => $name, 'description' => $description,
                'price' => $price, 'original_price' => $originalPrice, 'discount_percentage' => $discount,
                'category' => $category, 'brand' => $brand, 'image' => $image,
                'gallery' => [$image], 'rating' => $rating, 'review_count' => $reviews, 'sold_count' => $sold,
                'stock' => 40, 'min_order' => 1, 'condition' => 'Baru', 'availability' => 'Siap Dikirim',
                'supplier' => 'Toko Terverifikasi', 'specifications' => $specifications, 'variants' => [],
                'tags' => $tags, 'address' => $address, 'map_url' => $mapUrl,
                'latitude' => $coordinates[0], 'longitude' => $coordinates[1],
                'created_at' => now()->subDays($id),
            ];
        }, $items);
    }
